float dx = pj->position.x - pi->position.x;
float dy = pj->position.y - pi->position.y;
float dz = pj->position.z - pi->position.z;
float dist2 = dx*dx + dy*dy + dz*dz;
float dist = std::sqrt(dist2);
if (dist < 1e-6f) return;
float W = h - dist;
glm::vec3 dir = glm::vec3(dx, dy, dz) / dist;
float pressureForce = - (mass / pi->density) * (pi->pressure + pj->pressure) * spikyGrad * std::pow(W, 2);
force += dir * pressureForce;
float viscosityForce = viscosity * mass * (pj->velocity - pi->velocity) / pj->density * spikyLap * W;
force += dir * viscosityForce;

